import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return an empty grid for an empty grid — [] -> []");

  it.todo(
    "should kill a single live cell with 0 neighbors (underpopulation) — [(0,0)] -> []",
  );

  it.todo(
    "should kill both live cells when each has only 1 neighbor (underpopulation) — [(0,1), (1,1)] -> []",
  );

  it.todo(
    "should keep a live cell with 3 live neighbors alive (survival) — center (1,1) of `###`/`...`/`.#.` survives",
  );

  it.todo(
    "should kill a live cell with 4 live neighbors (overpopulation) — center (1,1) of `###`/`.#.`/`###` dies",
  );

  it.todo(
    "should bring a dead cell with exactly 3 live neighbors to life (reproduction) — (1,1) of `##.`/`#..`/`...` becomes alive",
  );

  it.todo(
    "should keep a block unchanged (still life) — [(0,0), (1,0), (0,1), (1,1)] -> unchanged",
  );

  it.todo(
    "should turn a vertical blinker horizontal — [(0,0), (0,1), (0,2)] -> [(-1,1), (0,1), (1,1)]",
  );

  it.todo(
    "should turn the horizontal blinker back to vertical — [(-1,1), (0,1), (1,1)] -> [(0,0), (0,1), (0,2)]",
  );

  it.todo(
    "should handle negative coordinates — a blinker at negative coordinates oscillates",
  );
});

