const rulesNext = (live) => {
  const key = ([x,y]) => `${x},${y}`;
  const set = new Set(live.map(key));
  const cand = new Map();
  for (const [x,y] of live)
    for (let dx=-1;dx<=1;dx++) for (let dy=-1;dy<=1;dy++)
      { const c=[x+dx,y+dy]; cand.set(key(c), c); }
  const out=[];
  for (const [k,[x,y]] of cand) {
    let n=0;
    for (let dx=-1;dx<=1;dx++) for (let dy=-1;dy<=1;dy++)
      if((dx||dy) && set.has(`${x+dx},${y+dy}`)) n++;
    if (set.has(k) ? (n===2||n===3) : n===3) out.push([x,y]);
  }
  return out.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);
};
