  neighbors >= MIN_NEIGHBORS_TO_SURVIVE &&
  neighbors <= MAX_NEIGHBORS_TO_SURVIVE;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) =>
    survives(countLiveNeighbors(cell, liveCells)),
  );
}

